tool_input.command:
$nodeScript = @'
import { chromium } from 'playwright'
import { PNG } from 'pngjs'
const browser = await chromium.launch({ headless: true })
const context = await browser.newContext({ viewport: { width: 100, height: 50 }, deviceScaleFactor: 3 })
const page = await context.newPage()
await page.setContent('<div style="width:100px;height:50px;background:#1680c0"></div>')
const buffer = await page.locator('div').screenshot({ scale: 'css' })
const image = PNG.sync.read(buffer)
console.log(`deviceScaleFactor=3, scale=css, output=${image.width}x${image.height}`)
await browser.close()
'@
node --input-type=module -e $nodeScript
